// la tarea "Contestar a {nombre}".
// Salida: un item con los cambios para registrar_cambios.
async function crearEnHubspot(asignados, ctx, extra) {
  const { config, hs, cal, ahora } = preparar(ctx, ['hubspot', 'horario']);
