      const [inicio, fin] = tramo.split('-').map(minutosDeHora);
      if (!(inicio < fin)) throw new Error(`Tramo inválido en HORARIO_LABORAL: "${tramo}"`);
      for (const d of dias) semana[d].push([inicio, fin]);
